let annualPricing=false;
function planFeatures(features){return `<ul class="plan-features">${features.map(t=>`<li>${icon('check',16)}<span>${t}</span></li>`).join('')}</ul>`}
function homepage(){const featured=jobs.find(j=>j.id===7);const signedIn=typeof Account!=='undefined'&&Boolean(Account.user),accountName=signedIn?(graduateProfile().name||Account.user.email||'Your account'):'';return `<div id="landing"><div class="landing-wrap"><div class="landing-nav"><a class="landing-brand" href="#home"><img src="assets/brand/nextwork-icon.png" alt="Nextwork logo">nextwork</a><div class="landing-nav-links"><a href="#home" onclick="event.preventDefault();scrollLanding('how-it-works')">How it works</a><a href="#explore">Find projects</a><a href="#organization">For organizations</a><a href="#pricing">Pricing</a></div><div class="landing-nav-actions">${signedIn?`<a class="landing-account" href="#profile" aria-label="Your account: ${esc(accountName)}"><span class="landing-account-avatar">${typeof profilePhotoMarkup==='function'?profilePhotoMarkup(Account.user.id,accountName):profileInitials(accountName)}</span><span class="landing-account-label">${esc(accountName)}</span></a><a class="primary" href="#overview">Open app ${icon('arrow',16)}</a>`:`<a class="mobile-plans" href="#pricing">Plans</a><a class="landing-login" href="#login">Log in</a><a class="primary" href="#signup">Get started free ${icon('arrow',16)}</a>`}</div></div><section class="landing-hero"><div class="landing-hero-copy"><div class="landing-kicker"><span></span> WHERE STARTUPS MEET NEW GRADS</div><h1>Your next chapter<br>starts with <em>work.</em></h1><p>Get paid to solve real startup problems. Build the experience, connections, and portfolio that move your career forward.</p><div class="landing-hero-actions"><a class="primary" href="${signedIn?'#overview':'#signup'}">${signedIn?'Open your workspace':'Create your free account'} ${icon('arrow',18)}</a><a class="landing-secondary" href="#explore">Explore projects ${icon('search',17)}</a></div><div class="landing-fineprint">Free to join. Free to apply. No card required.</div><div class="hero-skill-tags"><span>Development</span><span>Design</span><span>Data</span><span>Marketing</span><span>Business</span></div></div><div class="landing-hero-visual"><div class="visual-orbit"></div><div class="visual-note">YOUR NEXT CHAPTER ${icon('spark',16)}</div><div class="landing-project-card"><div class="project-card-header">${logo(featured)}<div><b>${featured.c}</b><small>Project spotlight · Remote</small></div><span class="project-budget">$${featured.pay.toLocaleString()}</span></div><h3>${featured.title}</h3><p>Own a clear deliverable. Collaborate with a startup. Build work you can show.</p><div class="tags">${featured.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="visual-deliverables"><span>${icon('check',15)} A real project brief</span><span>${icon('check',15)} A defined budget & timeline</span><span>${icon('check',15)} A portfolio-worthy outcome</span></div><a href="#project/${featured.id}">Explore this project ${icon('arrow',17)}</a></div><div class="visual-proof-badge">${icon('briefcase',21)}<div><b>Your contribution. Your proof.</b><small>Make your first project count.</small></div></div></div></section></div><div class="landing-principles"><span>${icon('briefcase')} Paid, scoped work</span><span>${icon('eye')} Transparent skill matching</span><span>${icon('message')} Direct startup connections</span><span>${icon('user')} Built for early careers</span></div><section class="landing-section" id="how-it-works"><div class="landing-section-heading"><div class="landing-kicker">A CLEAR NEXT STEP</div><h2>From “I can” to<br>“here’s what I built.”</h2><p>A small project can become your strongest story.</p></div><div class="how-grid">${[['01','user','Show what you bring','Add your skills, interests, and resume. See how your experience lines up with each opportunity.','Set up your profile','profile'],['02','briefcase','Find your kind of work','Choose a paid project with clear deliverables. Talk directly with the creator and apply as yourself.','Browse paid projects','explore'],['03','route','Build your next chapter','Own a contribution, document your decisions, and turn your experience into evidence for your next role.','Find your next project idea','recommend']].map(([n,i,h,p,label,url])=>`<article><div class="how-top">${icon(i,26)}<span>${n}</span></div><h3>${h}</h3><p>${p}</p><a href="#${url}">${label} ${icon('arrow',15)}</a></article>`).join('')}</div></section><section class="landing-fit"><div class="fit-art"><div class="fit-art-title">${icon('resume',23)} YOUR EXPERIENCE, MADE VISIBLE</div><div class="fit-art-line"><span class="fit-dot direct"></span><div><b>React & accessible interfaces</b><small>Direct listing evidence</small></div><span class="fit-status direct">Found</span></div><div class="fit-art-line"><span class="fit-dot support"></span><div><b>Team collaboration</b><small>Supporting field foundation</small></div><span class="fit-status support">Supporting</span></div><div class="fit-art-line"><span class="fit-dot gap"></span><div><b>API documentation</b><small>A next step to strengthen your story</small></div><span class="fit-status gap">Add evidence</span></div><div class="fit-art-caption">Illustrative evidence view · Missing evidence ≠ missing ability</div></div><div class="landing-fit-copy"><div class="landing-kicker">MORE CLARITY. BETTER NEXT STEPS.</div><h2>Know where you fit.<br>See where to grow.</h2><p>Match your resume against the project’s criteria and a transparent field rubric. See the evidence in color, and turn gaps into a practical plan.</p><a class="primary" href="#resume">Try resume matching ${icon('arrow',17)}</a><small>Instant matching is free. Optional AI uses available free-tier quota.</small></div></section><section class="landing-section pricing-section" id="pricing"><div class="landing-section-heading centered"><div class="landing-kicker">ONE PLAN. ALL FREE.</div><h2>Everything is included, for everyone.</h2><p>There is one general plan. Every Nextwork tool is available to every account at no cost.</p></div><div class="pricing-grid" style="grid-template-columns:minmax(0,520px);justify-content:center"><article class="price-card"><div class="plan-label">GENERAL PLAN</div><h3>Everything, included.</h3><div class="plan-price">$0<span> / month</span></div><p>Every tool, with no subscription required.</p><a class="primary" href="${signedIn?'#overview':'#signup'}">${signedIn?'Open app':'Create free account'} ${icon('arrow',16)}</a><div class="plan-includes">INCLUDED FOR EVERYONE</div>${planFeatures(['Browse, save, and apply to every project','Your graduate profile, portfolio & direct messaging','Resume matching, highlighted evidence & free-tier AI','Project ideas built from real job postings','Application overview and next-step planning'])}<small>No payment card required.</small></article></div><p class="pricing-footnote">AI stays on free-provider quota with no paid fallback.</p></section><section class="landing-section faq-section"><div><div class="landing-kicker">A LITTLE MORE CLARITY</div><h2>Before your first step.</h2></div><div>${[['Is the free plan enough to apply?','Yes. Every feature is free, including AI review within free-provider quota, applications, and messaging.'],['What kind of work will I find?','Short, paid projects with defined outcomes across development, design, data, marketing, and business. Read the brief, budget, and deliverables before applying.'],['Does a project guarantee a full-time job?','No. A project is a chance to build experience and a relationship. Any future role depends on the startup’s needs and a separate hiring decision.'],['How is AI kept free?','Core matching runs locally without a key. Optional Gemini analysis uses the configured free-tier project and falls back to free text checks when quota is unavailable.']].map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div></section><section class="landing-final"><div class="landing-kicker">YOUR FIRST BIG STEP</div><h2>Start with a project.<br>Build a career you can point to.</h2><a class="primary" href="${signedIn?'#overview':'#signup'}">${signedIn?'Open app':'Get started free'} ${icon('arrow',18)}</a><a href="#explore" class="landing-final-link">Or explore the marketplace →</a></section><div class="landing-footer"><a href="#home" class="landing-brand"><img src="assets/brand/nextwork-icon.png" alt="">nextwork</a><span>Real work. Real momentum.</span><div><a href="#explore">Find work</a><a href="#pricing">Plans</a><a href="#settings">Workspace settings</a></div></div></div>`}
function scrollLanding(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function setPricing(annual){annualPricing=annual;render();scrollLanding('pricing')}
